#include <stdio.h>

int main()
{
    int a, b, c;
    scanf("%d%d%d", &a, &b, &c);
    if (a + b <= c || a + c <= b || b + c <= a)
        printf("none\n");
    else if (a == b && b == c)
        printf("equilateral\n");
    else if (a * a + b * b == c * c || a * a + c * c == b * b || b * b + c * c == a * a)
        printf("right\n");
    else if (a == b || b == c || a == c)
        printf("isosceles\n");
    else
        printf("scalene\n");
    return 0;
}

